document.addEventListener('DOMContentLoaded', () => {
  initCarousel();
  initSmoothScroll();
  initScrollSpy();
  initGallery();
  initContactForm();
  updateCopyrightYear();
});

function initCarousel() {
  const carouselEl = document.getElementById('heroCarousel');
  if (!carouselEl) return;

  new bootstrap.Carousel(carouselEl, {
    interval: 5000,
    pause: 'hover',
    wrap: true,
    ride: 'carousel',
  });
}

function initSmoothScroll() {
  const navbar = document.querySelector('.navbar');
  const navHeight = navbar ? navbar.offsetHeight : 0;

  document.querySelectorAll('a[href^="#"]').forEach((link) => {
    const href = link.getAttribute('href');

    if (href === '#') {
      link.addEventListener('click', (e) => {
        e.preventDefault();
        scrollToSection(document.getElementById('contact'), navHeight);
      });
      return;
    }

    const target = document.querySelector(href);
    if (!target) return;

    link.addEventListener('click', (e) => {
      e.preventDefault();
      scrollToSection(target, navHeight);
      closeMobileMenu();
    });
  });
}

function scrollToSection(target, offset = 0) {
  if (!target) return;
  const top = target.getBoundingClientRect().top + window.pageYOffset - offset + 1;
  window.scrollTo({ top, behavior: 'smooth' });
}

function closeMobileMenu() {
  const collapseEl = document.getElementById('navbarNav');
  if (collapseEl && collapseEl.classList.contains('show')) {
    bootstrap.Collapse.getOrCreateInstance(collapseEl).hide();
  }
}

function initScrollSpy() {
  if (!document.getElementById('navbarNav')) return;

  new bootstrap.ScrollSpy(document.body, {
    target: '#navbarNav',
    offset: 90,
  });
}

function initGallery() {
  const gallery = document.getElementById('gallery');
  const modalEl = document.getElementById('imageModal1');
  if (!gallery || !modalEl) return;

  const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
  const modalImg = modalEl.querySelector('.modal-body img');
  const modalTitle = modalEl.querySelector('.modal-title');

  gallery.querySelectorAll('img').forEach((img) => {
    img.removeAttribute('data-bs-toggle');
    img.removeAttribute('data-bs-target');

    img.setAttribute('tabindex', '0');
    img.setAttribute('role', 'button');
    img.setAttribute('aria-label', `Открыть фото: ${img.alt || 'просмотр'}`);

    const openModal = () => {
      modalImg.src = img.currentSrc || img.src;
      modalImg.alt = img.alt || 'Просмотр фотографии';
      modalTitle.textContent = img.alt || 'Просмотр фотографии';
      modal.show();
    };

    img.addEventListener('click', openModal);
    img.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        openModal();
      }
    });
  });
}

function initContactForm() {
  const form = document.querySelector('#contact form');
  if (!form) return;

  const agree = form.querySelector('#agree');

  if (agree) {
    agree.addEventListener('change', () => agree.setCustomValidity(''));
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    
    if (agree && !agree.checked) {
      agree.setCustomValidity('Необходимо согласие на обработку персональных данных');
    } else if (agree) {
      agree.setCustomValidity('');
    }

    if (!form.reportValidity()) return;

    showFormSuccess(form);

    form.reset();
    form.querySelectorAll('.is-invalid').forEach((el) => el.classList.remove('is-invalid'));
  });
}

function showFormSuccess(form) {
  const oldAlert = form.parentElement.querySelector('.js-form-success');
  if (oldAlert) oldAlert.remove();

  const alert = document.createElement('div');
  alert.className = 'alert alert-success mt-3 js-form-success';
  alert.setAttribute('role', 'alert');
  alert.textContent = 'Спасибо! Ваша заявка отправлена. Мы свяжемся с вами в ближайшее время.';

  form.insertAdjacentElement('afterend', alert);

  setTimeout(() => alert.remove(), 6000);
}

function updateCopyrightYear() {
  const copyright = document.querySelector('footer p.text-center');
  if (!copyright) return;
  copyright.textContent = copyright.textContent.replace(/\d{4}/, new Date().getFullYear());
}